<?php
namespace App\Jobs;use App\Contracts\FaceProvider;use App\Models\IndexedFace;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};
class RemoveIndexedFaces implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public function __construct(public array$collections){$this->onQueue('maintenance');}public function handle(FaceProvider$p):void{foreach($this->collections as$collection)$p->removeFaces($collection['collection'],$collection['face_ids']);}}
